<template><div><h1>Buildings</h1><p>Organise buildings within each site.</p><div class="panel"><h2>Add building</h2><form class="form" @submit.prevent="add"><label>Site</label><select v-model="siteId" required><option value="" disabled>Select a site</option><option v-for="s in sites" :key="s.id" :value="s.id">{{s.name}}</option></select><label>Building name</label><input v-model="name" maxlength="120" required placeholder="Administration"><label>Description (optional)</label><input v-model="description" maxlength="500"><button class="btn" :disabled="saving || !isAdmin">{{saving?'Saving…':'Add building'}}</button></form><p v-if="!isAdmin" class="muted">Only administrators can change records.</p></div><div class="panel"><h2>All buildings</h2><p v-if="loading">Loading…</p><table v-else class="table"><thead><tr><th>Building</th><th>Site</th><th>Description</th><th v-if="isAdmin">Actions</th></tr></thead><tbody><tr v-for="b in buildings" :key="b.id"><td>{{b.name}}</td><td>{{siteName(b.site_id)}}</td><td>{{b.description||'—'}}</td><td v-if="isAdmin"><button class="btn" @click="remove(b.id)">Delete</button></td></tr><tr v-if="!buildings.length"><td colspan="4">No buildings yet.</td></tr></tbody></table></div><p v-if="error" class="danger">{{error}}</p></div></template>
<script setup lang="ts">
definePageMeta({middleware:'auth'});const client=useSupabaseClient();const {isAdmin,refreshRole}=useAccess();const sites=ref<any[]>([]),buildings=ref<any[]>([]);const siteId=ref(''),name=ref(''),description=ref(''),error=ref(''),saving=ref(false),loading=ref(true)
const siteName=(id:string)=>sites.value.find(s=>s.id===id)?.name||'Unknown'
async function load(){loading.value=true;const [s,b]=await Promise.all([client.from('sites').select('id,name').order('name'),client.from('buildings').select('id,site_id,name,description').order('name')]);sites.value=s.data||[];buildings.value=b.data||[];error.value=s.error?.message||b.error?.message||'';loading.value=false}
async function add(){saving.value=true;error.value='';const {error:e}=await client.from('buildings').insert({site_id:siteId.value,name:name.value.trim(),description:description.value.trim()||null});if(e)error.value=e.message;else{name.value='';description.value='';await load()}saving.value=false}
async function remove(id:string){if(!confirm('Delete this building?'))return;const {error:e}=await client.from('buildings').delete().eq('id',id);if(e)error.value=e.message;else await load()}
onMounted(async()=>{try{await refreshRole();await load()}catch(e:any){error.value=e.message}})
</script>
